 "command": "python3 - <<'PY'
# encode source, output rows and test hypothesized cyclic sequence via column paths
src=[[7,7,5,7,5,6,5,6],[5,5,7,5,7,6,6,6],[7,7,5,6,7,5,7,6],[7,5,7,7,7,6,7,5],[5,6,7,7,6,5,7,5],[5,6,6,6,6,6,7,6],[6,5,7,6,5,6,5,6]]
out=[[6,5,6,5,6,7,5,6,6,5,7,6,5,6,5,6],[6,7,6,6,6,6,6,5,5,6,6,6,6,6,7,6],[5,7,5,6,7,7,6,5,5,6,7,7,6,5,7,5],[5,7,6,7,7,7,5,7,7,5,7,7,7,6,7,5],[6,7,5,7,6,5,7,7,7,7,5,6,7,5,7,6],[6,6,6,7,5,7,5,5,5,5,7,5,7,6,6,6],[6,5,6,5,7,5,7,7,7,7,5,7,5,6,5,6]]
# locate each output row as source rows/cols patterns
for r in out:
 for c in (r[:8],r[8:]):
  matches=[]
  for i,row in enumerate(src):
   if c==row: matches.append(('r',i))
   if c==row[::-1]: matches.append(('rr',i))
  print(matches,end=' ')
 print()
